DROP TABLE IF EXISTS `priority_queue`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `priority_queue` (
  `queue_id` int(11) NOT NULL AUTO_INCREMENT,
  `item_type` varchar(50) NOT NULL,
  `item_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL COMMENT 'Przechowuje dane jako JSON (ID galerii, nazwa modelu itp.)' CHECK (json_valid(`item_data`)),
  `priority` int(11) DEFAULT 100 COMMENT 'Niższa wartość = wyższy priorytet',
  `added_timestamp` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`queue_id`)
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
